from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from constance import config

class TenantFeatureToggleView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, tenant_slug):
        if request.user.tenant.slug != tenant_slug or not request.user.is_tenant_admin:
            return Response({"error": "Access denied to tenant feature configuration"}, status=403)

        flag_name = request.data.get("feature_flag")
        enabled = request.data.get("enabled", False)

        constance_key = f"FLAG_{tenant_slug.upper()}_{flag_name.upper()}"
        if not hasattr(config, constance_key):
            return Response({"error": "Invalid feature flag for tenant"}, status=400)

        setattr(config, constance_key, bool(enabled))
        return Response({"tenant": tenant_slug, "feature": flag_name, "enabled": enabled})
